using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static class InstallTreeInstancingShaders {
 const string Work="Recovery/DrawCalls_20261107";const string Output="Assets/SceneOptimization/Generated/Shaders";
 public static object Run(){if(EditorApplication.isPlaying||EditorApplication.isCompiling)throw new Exception("Edit Mode required");var mats=Terrain.activeTerrains.SelectMany(t=>t.terrainData.treePrototypes).SelectMany(p=>p.prefab.GetComponentsInChildren<MeshRenderer>(true)).SelectMany(r=>r.sharedMaterials).Where(m=>m&&m.HasProperty("_Color")&&m.shader.name.StartsWith("FoggyRoad/Optimization/Graph/")&&!m.shader.name.EndsWith("/Tree Instanced")).Distinct().ToArray();if(mats.Length!=10)throw new Exception("Expected10 validated pine materials, got"+mats.Length);var map=new Dictionary<Shader,Shader>();foreach(var source in mats.Select(m=>m.shader).Distinct()){string path=AssetDatabase.GetAssetPath(source);string code=File.ReadAllText(path);if(!code.Contains("float4 _Color;"))throw new Exception("Source layout changed");code=code.Replace("Shader \""+source.name+"\"","Shader \""+source.name+" Instanced\"").Replace("float4 _Color;","").Replace("CBUFFER_START(UnityPerMaterial)","// Bind this material property outside UnityPerMaterial so native Terrain pine draws\n// use GPU instancing instead of separate SRP Batcher draws. Values and shading are unchanged.\nfloat4 _Color;\nCBUFFER_START(UnityPerMaterial)");string target=Output+"/"+Path.GetFileNameWithoutExtension(path)+"_Instanced.shader";File.WriteAllText(target,code);AssetDatabase.ImportAsset(target,ImportAssetOptions.ForceSynchronousImport);var variant=AssetDatabase.LoadAssetAtPath<Shader>(target);if(!variant||ShaderUtil.ShaderHasError(variant))throw new Exception("Shader import failed: "+target);map[source]=variant;}
 var report=new System.Text.StringBuilder("material\toriginalShader\tinstancedShader\n");Directory.CreateDirectory(Work+"/MaterialBackups");foreach(var m in mats){string path=AssetDatabase.GetAssetPath(m);File.Copy(path,Work+"/MaterialBackups/"+Path.GetFileName(path),true);report.AppendLine(path+"\t"+AssetDatabase.GetAssetPath(m.shader)+"\t"+AssetDatabase.GetAssetPath(map[m.shader]));}File.WriteAllText(Work+"/InstalledMaterialShaders.tsv",report.ToString());Undo.RecordObjects(mats,"Instance native Terrain pine draws");foreach(var m in mats){m.shader=map[m.shader];EditorUtility.SetDirty(m);AssetDatabase.SaveAssetIfDirty(m);}return "Saved2 pine instancing shader variants and10 material bindings; source shaders, terrain, meshes, colliders and density unchanged";}
}
